import{esc,input,select,button}from'../phase4/ui.js';
import{events,counts,bins,five,clock,correlation,lineAt}from'./b20-model.js';
const btn=(a,l,attrs='')=>button('b20-'+a,l,attrs),sel=select,f=input;
const note=s=>`<p class="b20-note">${s}</p>`,card=s=>`<div class="b20-card">${s}</div>`;
const table=(heads,rows)=>`<table class="b20-table"><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const colors=['#7b91bd','#b78859','#6e9c83','#ac84ac','#bb9d43'];
const label=(x,y,s,more='')=>`<text x="${x}" y="${y}" ${more}>${esc(s)}</text>`;
const line=(x1,y1,x2,y2,more='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" ${more}/>`;
const dot=(x,y,color=colors[0],r=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const svg=(body,title,h=320)=>`<svg class="b20-graph" viewBox="0 0 680 ${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>${body}</svg>`;
const fmt=(n,d=1)=>{const gcd=(a,b)=>b?gcd(b,a%b):a;if(d===1)return String(n);const whole=Math.floor(n/d),rest=n%d;if(!rest)return String(whole);const g=gcd(rest,d);return(whole?whole+' ':'')+rest/g+'/'+(d/g);};
function plane(t,ps,{bar=false,connect=false,ymax=t.yDomain[1],tick=t.yTicks?.[0]||t.yTicks?.[0]||5,ends=null}={}){const X=x=>t.labels?62+(x+.5)/t.labels.length*560:62+(x-t.xDomain[0])/(t.xDomain[1]-t.xDomain[0])*560,Y=y=>258-(y-t.yDomain[0])/(ymax-t.yDomain[0])*212;let s='';
 for(let y=t.yDomain[0];y<=ymax+1e-9;y+=tick)s+=line(62,Y(y),622,Y(y),'class="grid"')+label(50,Y(y)+4,y,'text-anchor="end"');
 const step=t.xTicks?.[0]||1;for(let x=t.xDomain[0];x<=(t.labels?t.labels.length-1:t.xDomain[1])+1e-9;x+=step)s+=line(X(x),258,X(x),263)+label(X(x),280,t.labels?.[x]??x,'text-anchor="middle"');
 s+=line(62,40,62,258)+line(62,258,630,258)+label(62,22,t.ylabel)+label(340,310,t.xlabel,'text-anchor="middle"');
 if(connect){const p=ps.filter(Boolean).slice().sort((a,b)=>a[0]-b[0]);s+=`<polyline points="${p.map(([x,y])=>X(x)+','+Y(y)).join(' ')}" fill="none" stroke="${colors[0]}" stroke-width="2.5"/>`;}
 ps.forEach(p=>{if(!p)return;const[x,y]=p;s+=bar?`<rect x="${X(x)-20}" y="${Y(y)}" width="40" height="${258-Y(y)}" fill="${colors[0]}"/>`:dot(X(x),Y(y));});
 if(ends)s+=line(X(t.xDomain[0]),Y(ends[0]),X(t.xDomain[1]),Y(ends[1]),`stroke="${colors[1]}" stroke-width="3"`);
 return svg(s,`${t.xlabel}与${t.ylabel}，${connect?'按时间连接':'按数值位置排列'}`);
}
function dotsPlot(values,min,max,d=1,unit='',second=null,cluster=null){const X=n=>64+(n-min)/(max-min)*560,draw=(vs,y,col)=>{let s='',stacks={};for(const n of vs.filter(v=>v!==null)){stacks[n]=(stacks[n]||0)+1;s+=dot(X(n),y-stacks[n]*16,col,5.5);}return s;};let s='';if(cluster)s+=`<rect x="${X(cluster[0])}" y="26" width="${X(cluster[1])-X(cluster[0])}" height="156" fill="#dce9d6"/>`;
 s+=line(64,180,624,180);for(let n=min;n<=max;n+=1)s+=line(X(n),180,X(n),185)+label(X(n),204,fmt(n,d),'text-anchor="middle"');s+=draw(values,180,colors[0])+label(64,20,second?'甲组 · 一点一份记录':'一点一份记录');if(second)s+=draw(second,356,colors[1])+line(64,356,624,356)+label(64,235,'乙组 · 与甲组同一把尺');s+=label(340,second?385:237,unit,'text-anchor="middle"');return svg(s,'点的位置表示记录值，堆叠表示次数；空刻度保留',second?410:260);}
function grouped(labels,a,b,unit='人'){const ymax=Math.ceil(Math.max(...a,...(b||[]),1)/2)*2,X=i=>110+i*500/labels.length,Y=n=>245-n/ymax*190;let s=label(55,24,unit);for(let n=0;n<=ymax;n+=Math.max(1,ymax/5))s+=line(60,Y(n),620,Y(n),'class="grid"')+label(48,Y(n)+4,Math.round(n*10)/10,'text-anchor="end"');labels.forEach((l,i)=>{s+=`<rect x="${X(i)}" y="${Y(a[i])}" width="30" height="${245-Y(a[i])}" fill="${colors[0]}"/>`+label(X(i)+15,Y(a[i])-7,a[i],'text-anchor="middle"');if(b)s+=`<rect x="${X(i)+33}" y="${Y(b[i])}" width="30" height="${245-Y(b[i])}" fill="${colors[1]}"/>`+label(X(i)+48,Y(b[i])-7,b[i],'text-anchor="middle"');s+=label(X(i)+(b?32:15),272,l,'text-anchor="middle"');});s+=label(340,308,b?'蓝：A组　棕：B组':'每类的数量','text-anchor="middle"');return svg(s,'同一零点和刻度的类别柱图');}
function picture(ls,ns,scale){return note(`图例：一个完整的 ● 代表 ${scale} 份；半个代表 ${scale/2} 份。`)+`<div class="b20-pictures">${ls.map((l,i)=>`<div><b>${esc(l)}</b><span>${Array.from({length:Math.ceil(ns[i]/scale)},(_,j)=>`<i style="--part:${Math.min(1,ns[i]/scale-j)*100}%" aria-label="${Math.min(scale,ns[i]-j*scale)}份"></i>`).join('')}</span></div>`).join('')}</div>`;}
function piePlot(t,angles){let start=-90,s='',total=angles.reduce((s,n)=>s+(n||0),0);angles.forEach((n,i)=>{if(!n)return;const end=start+n,R=112,xy=a=>[230+R*Math.cos(a*Math.PI/180),145+R*Math.sin(a*Math.PI/180)],p=xy(start),q=xy(end);s+=n>=360?`<circle cx="230" cy="145" r="112" fill="${colors[i]}"/>`:`<path d="M230 145 L${p} A112 112 0 ${n>180?1:0} 1 ${q} Z" fill="${colors[i]}" stroke="#fff" stroke-width="2"/>`;start=end;});s+=`<circle cx="230" cy="145" r="112" fill="none" stroke="#c7cec4"/>`;t.labels.forEach((l,i)=>s+=dot(390,85+i*40,colors[i])+label(404,90+i*40,l+'：'+(angles[i]??'—')+'°'));s+=label(230,295,'已拼 '+Math.round(total*100)/100+'° / 360°','text-anchor="middle"');return svg(s,'整圈代表全部；各扇区按已放角度绘制');}
function histogram(t,b){const bs=bins(t,b.width),ns=bs.map((_,i)=>b.placed.filter(v=>v===i).length),max=Math.max(4,...ns),X=x=>62+(x-t.start)/(t.end-t.start)*560,Y=n=>248-n/max*200;let s=label(62,22,'人数 / 记录次数');for(let n=0;n<=max;n+=Math.max(1,Math.ceil(max/5)))s+=line(62,Y(n),622,Y(n),'class="grid"')+label(50,Y(n)+4,n,'text-anchor="end"');bs.forEach(([lo,hi],i)=>{s+=`<rect x="${X(lo)}" y="${Y(ns[i])}" width="${X(hi)-X(lo)}" height="${248-Y(ns[i])}" fill="${colors[0]}" stroke="#fafbf6" stroke-width="1"/>`+label((X(lo)+X(hi))/2,Y(ns[i])-6,ns[i],'text-anchor="middle"')+label(X(lo),275,lo,'text-anchor="middle"');});s+=label(X(t.end),275,t.end,'text-anchor="middle"')+label(340,310,t.unit+' · 含左边界，不含右边界','text-anchor="middle"');return svg(s,'相接的等宽区间，柱高表示频数');}
function boxes(t,b){const X=n=>62+(n-t.domain[0])/(t.domain[1]-t.domain[0])*560;let s='';const draw=(v,y,name)=>{let z=label(62,y-45,name);v.forEach((n,i)=>{if(n!==null)z+=line(X(n),y-19,X(n),y+19,`stroke="${colors[0]}" stroke-width="2"`)+label(X(n),y+40,n,'text-anchor="middle"');});if(v.every(n=>n!==null))z+=line(X(v[0]),y,X(v[4]),y)+`<rect x="${X(v[1])}" y="${y-20}" width="${X(v[3])-X(v[1])}" height="40" fill="#dee5f0" stroke="${colors[0]}"/>`+line(X(v[2]),y-20,X(v[2]),y+20,'stroke="#455e85" stroke-width="3"');return z;};s+=draw(t.mode==='hidden'?five(b.values):b.marks,90,t.mode==='compare'?'第一组':'最小 — 中间一半 — 最大');if(t.second)s+=draw(t.second,230,'第二组');s+=line(62,t.second?295:180,622,t.second?295:180);const tick=(t.domain[1]-t.domain[0])/(t.domain[1]===24?8:7);for(let n=t.domain[0];n<=t.domain[1];n+=tick)s+=label(X(n),t.second?317:202,n,'text-anchor="middle"');s+=label(340,t.second?345:230,t.unit||'数值（最小最大须线）','text-anchor="middle"');return svg(s,'五数概括，箱子中间一半，须线到最小最大',t.second?370:250);}
const roster=(ls,b)=>`<details class="b20-roster"><summary>回到某一条更正</summary><div>${ls.map((s,i)=>btn('row',esc(s),`data-index="${i}" aria-pressed="${b.cursor===i}"`)).join('')}</div></details>`;
const revise=(content,done)=>done?`<details class="b20-revise"><summary>已经放齐 · 修改图上的记录</summary>${content}</details>`:content;
const qfields=(t,m)=>`<div class="b20-fields">${(t.questions||[]).map((q,i)=>q.options?sel('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i])).join('')}</div>`;
const axes=(t,m,kind=false)=>`<div class="b20-fields">${sel('xaxis','横着这把尺表示',m.xaxis,kind?[['interval',t.unit+'的连续区间'],['frequency','出现次数']]:[['x',t.xlabel],['y',t.ylabel]])}${sel('yaxis','竖着这把尺表示',m.yaxis,kind?[['frequency','记录次数'],['interval',t.unit+'的数值']]:[['x',t.xlabel],['y',t.ylabel]])}</div>`;
export function visual(t,m){const b=m.board;let v='';
 if(t.type==='x-eventchart'){const pending=b.draws.length>b.records.length;v=card(`<small>已记 ${b.records.length}/${events(t).length} 条</small><h3>${pending?esc(t.labels[b.draws.at(-1)]):b.records.length===events(t).length?'都记下来了':'点“观察下一次”，再记一笔'}</h3>`);const ns=counts(b.records,t.labels);v+=b.view==='picture'?picture(t.labels,ns,t.scale):table(['类别','次数'],t.labels.map((l,i)=>[l,ns[i]]));}
 if(t.type==='x-timeplot'){v=plane(t,b.points,{bar:t.kind==='category'&&m.chart==='bar',connect:t.kind==='time'&&b.connected,ymax:t.changeScale?t.yDomain[1]*b.scale/t.yTicks[0]:t.yDomain[1],tick:b.scale});if(t.build)v+=card(`原记录 ${b.cursor+1}/${t.points.length}：<b>${esc(t.labels?.[t.points[b.cursor][0]]??t.points[b.cursor][0])} → ${t.points[b.cursor][1]}</b><br>${esc(t.xlabel)} → ${esc(t.ylabel)}`);if(t.period)v+=note('每个点是整月总量。线段不是某一天的实测雨量。');}
 if(t.type==='x-timetable'){if(t.mode==='journey')v=card(`<small>${clock(t.start)} 出发 → ${clock(t.end)} 到达</small><h3>现在走到 ${clock(b.time)}</h3><p>${b.hops.length?b.hops.map(n=>'＋'+n+'分钟').join(' → '):'先选一段分钟向前走'}</p>`);else v=table(['站点 / 分组',...t.cols],t.grid.map((r,i)=>[t.rows[i],...r.map((v,j)=>v??m.cells[t.missing?.findIndex(x=>x[0]===i&&x[1]===j)]??'—')]))+(b.cell?card(`选中：${esc(t.rows[b.cell[0]])} × ${esc(t.cols[b.cell[1]])} = <b>${esc(t.grid[b.cell[0]][b.cell[1]])}</b>`):'');}
 if(t.type==='x-dotdraw'){const low=Number(m.low),high=Number(m.high);v=dotsPlot(b.placed,t.min,t.max,t.d,t.unit,null,t.cluster&&m.low!==''&&m.high!==''&&low<=high?[low,high]:null);if(!t.given)v+=card(`原记录 ${b.cursor+1}/${t.values.length}：<b>${fmt(t.values[b.cursor],t.d)} ${esc(t.unit)}</b> · 已放 ${b.placed.filter(v=>v!==null).length} 个点`);if(t.fair)v+=note('上图一直保留倒水前的记录；下面是现在的四杯。')+`<div class="b20-cups">${b.cups.map((n,i)=>`<div><span style="height:${n/t.max*100}%"></span><b>${i+1}号：${fmt(n,t.d)}</b></div>`).join('')}</div>`;}
 if(t.type==='x-piesector')v=piePlot(t,b.angles)+table(['类别','原票数 / 人数'],t.labels.map((l,i)=>[l,t.counts[i]]))+note(`总数 ${t.counts.reduce((s,n)=>s+n,0)}。${t.otherTotal?'另一个整体是'+t.otherTotal+'人，足球仍占120°。':''}`);
 if(t.type==='x-histbuild')v=histogram(t,b)+(t.given?note('这一步只提供分组后的图，原始身高没有显示。'):card(`原记录 ${b.cursor+1}/${t.values.length}：<b>${t.values[b.cursor]} ${esc(t.unit)}</b> · 已归组 ${b.placed.filter(n=>n!==null).length} 条`));
 if(t.type==='x-boxsummary'){v=boxes(t,b);if(t.mode==='build')v+=table(['位置','原记录中的五个数'],['最小','下半组的中间','全组的中间','上半组的中间','最大'].map((l,i)=>[l,t.summary[i]]));if(t.mode==='hidden')v+=table(['记录组','从小到大'],[['可修改这组',b.values.join('，')],['另一组',t.other.join('，')]])+note('找五个位置的方法：排序后找全组和上下半组的中间；若有奇数个，不把全组中间那个重复计入两半。重复值可能让分界处有并列。');}
 if(t.type==='x-scatterbuild')v=plane(t,b.points,{ends:b.line,tick:t.yTicks[0]})+card(`原记录 ${b.cursor+1}/${t.points.length}：<b>${t.points[b.cursor][0]} → ${t.points[b.cursor][1]}</b><br>${esc(t.xlabel)} → ${esc(t.ylabel)} · 已放 ${b.points.filter(Boolean).length} 点`);
 if(t.type==='x-graphcompare'){if(t.mode==='represent')v=b.view==='picture'?picture(t.labels,t.a,t.scale):grouped(t.labels,t.a,null,t.unit);else if(t.mode==='distributions')v=b.view==='dot'?dotsPlot(t.a,140,165,1,t.unit,t.b):table(['甲组','乙组'],t.a.map((n,i)=>[n,t.b[i]]));else v=grouped(t.labels,t.a,t.b,t.unit);}
 if(t.type==='x-correlationlab'){if(!b.started)v=card('<h3>把同一片点云拉高，会更有联系吗？</h3><p>先留下猜想，再动一动。</p>');else{const ps=t.points.map(([x,y])=>[x,(b.tight?(y+x+2)/2:y)*b.scale]);v=plane({...t,xlabel:'气温（℃）',ylabel:'销量（份）',xTicks:[2],yTicks:[10],yDomain:[0,80]},ps,{tick:10})+note(`这组模拟点同向变化的紧密程度 ≈ ${correlation(ps).toFixed(3)}（越接近1越紧）。拉伸倍数 ${b.scale}；${b.tight?'点已朝共同趋势收拢':'原始散开程度'}。`)+table(['模拟气温','冰淇淋份数','游泳人数'],b.weather.map(v=>[v,2*v+5,3*v]))+note('这里人为设定：冰淇淋=2×气温+5，游泳人数=3×气温。只是展示“共同因素”的可能性，不是对真实世界的因果证明。');}}
 return`<div class="b20-world">${note('模拟记录 · 先操作，再比较你发现的变化')}${v}</div>`;
}
export function controls(t,m){const b=m.board;let v='';
 if(t.type==='x-eventchart'){const pending=b.draws.length>b.records.length;v=pending?t.labels.map((l,i)=>btn('tally','给'+esc(l)+'记一笔',`data-index="${i}"`)).join(''):b.records.length<events(t).length?btn('observe','观察下一次'):btn('view','换成图画',`data-kind="picture"`)+btn('view','换成表格',`data-kind="table"`);if(b.records.length===events(t).length)v+=`<div class="b20-fields">${f('value','一共几条记录',m.value)}${sel('high','数量最多的一类（并列选任意一类）',m.high,t.labels.map((l,i)=>[String(i),l]))}${sel('low','数量最少的一类（并列选任意一类）',m.low,t.labels.map((l,i)=>[String(i),l]))}</div>`;}
 if(t.type==='x-timeplot'||t.type==='x-scatterbuild'){
  if(t.build||t.type==='x-scatterbuild')v+=revise(axes(t,m)+(t.type==='x-timeplot'?sel('chart','这些记录怎么画',m.chart,[['line','按实际时间位置连线'],['bar','分开的类别柱子']]):'')+`<div class="b20-fields">${f('x',t.kind==='category'?'类别位置（苹果0、香蕉1、梨2）':'横着的数值',m.x)}${f('y','竖着的数值',m.y)}</div>${btn('point','把这份记录放上去')}${roster(t.points.map((_,i)=>'第'+(i+1)+'份'),b)}`,b.points.every(Boolean));
  if(t.type==='x-timeplot'&&t.build&&b.points.every(Boolean)&&t.kind==='time')v+=btn('connect','按时间把点连起来');
  if(t.type==='x-timeplot'&&t.changeScale)v+=sel('tick','纵轴每格表示',m.tick,t.yTicks.map(n=>[String(n),n+'℃']))+btn('scale','换一把刻度尺');
  if(t.type==='x-scatterbuild'&&b.points.every(Boolean)){v+=sel('trend','这些点整体怎样走',m.trend,[['positive','大致向右上方'],['negative','大致向右下方'],['none','没有明显直线趋势']]);v+=`<div data-b20-fit ${m.trend==='none'?'hidden':''}>`+note(`用左右边界上的高度确定一条直线。可以反复调；不需要穿过每一点。`)+`<div class="b20-fields">${f('left',`横轴${t.xDomain[0]}处的线高`,m.left)}${f('right',`横轴${t.xDomain[1]}处的线高`,m.right)}</div>${btn('line','画这条直线')}${f('prediction',`用自己的线估计横轴${t.predict}时的值（可取到整数）`,m.prediction)}</div>`;if(t.outside)v+=sel('outside',`${t.outside}℃超出观察范围时`,m.outside,[['caution','关系可能改变，不能直接相信延长线'],['sure','延长线一定准确']]);}
 }
 if(t.type==='x-timetable'){if(t.mode==='read')v+=`<div class="b20-fields">${sel('row','哪一行',m.row,t.rows.map((s,i)=>[String(i),s]))}${sel('col','哪一列',m.col,t.cols.map((s,i)=>[String(i),s]))}</div>${btn('cell','看这个交点')}`;if(t.mode==='grid')v+=`<div class="b20-fields">${t.missing.map(([r,c],i)=>f('cells.'+i,t.rows[r]+' · '+t.cols[c],m.cells[i])).join('')}</div>`;if(t.mode==='journey')v+=f('jump','这一步向前走几分钟',m.jump)+btn('jump','向前走这些分钟',b.time===t.end?'disabled':'');}
 if(t.type==='x-dotdraw'){if(!t.given)v+=revise(f('value','把这条记录放在哪个数值（分数可写1/2）',m.value)+btn('dot','放上这个点')+roster(t.values.map((_,i)=>'记录'+(i+1)),b),b.placed.every(n=>n!==null));if(t.fair&&b.placed.every(n=>n!==null))v+=`<div class="b20-fields">${sel('from','从哪杯倒出',m.from,t.values.map((_,i)=>[String(i),(i+1)+'号杯']))}${sel('to','倒进哪杯',m.to,t.values.map((_,i)=>[String(i),(i+1)+'号杯']))}</div>${btn('transfer','倒过去1/8杯')}`;if(t.cluster)v+=`<div class="b20-fields">${f('low','圈住大多数值：左端',m.low)}${f('high','圈住大多数值：右端',m.high)}</div>`;}
 if(t.type==='x-piesector'&&t.mode!=='read')v+=note(`现在给「${esc(t.labels[b.cursor])}」拼一块。`)+f('angle','这块要多少度',m.angle)+btn('sector','拼上这块')+roster(t.labels,b);
 if(t.type==='x-histbuild'){v+=axes(t,m,true);if(t.widths.length>1)v+=sel('width','每格多宽',m.width,t.widths.map(w=>[String(w),w+t.unit]))+btn('width','改宽度，重新归组');if(!t.given)v+=note('把当前这条原记录放到一个区间里：')+`<div class="b20-bin-buttons">${bins(t,b.width).map(([lo,hi],i)=>btn('bin',`${lo} ≤ 数值 < ${hi}`,`data-index="${i}"`)).join('')}</div>`+roster(t.values.map((_,i)=>'记录'+(i+1)),b);}
 if(t.type==='x-boxsummary'){if(t.mode==='build')v+=note('现在放：'+['最小','下半组的中间','全组的中间','上半组的中间','最大'][b.cursor])+f('value','放在尺上的哪个数',m.value)+btn('mark','放好这个位置')+roster(['最小','下半组的中间','全组的中间','上半组的中间','最大'],b);if(t.mode==='hidden')v+=`<div class="b20-fields">${sel('index','改哪一个内部数',m.index,t.data.flatMap((n,i)=>i>0&&i<t.data.length-1?[[String(i),'第'+(i+1)+'个（原来'+n+'）']]:[]))}${f('value','改成什么值',m.value)}</div>${btn('alter','试改一下，看五个位置')}`;}
 if(t.type==='x-graphcompare'){if(t.mode==='represent')v+=btn('view','看柱图','data-kind="bar"')+btn('view','看图画','data-kind="picture"')+sel('best','这次想用哪一种',m.best,[['bar','柱图'],['picture','图画']])+sel('reason','选它来做什么',m.reason,[['exact','比较高度与准确的差'],['groups','按图例看几组相同数量'],['big','装饰更大就表示更多']]);else if(t.mode==='distributions')v+=btn('view','用同一把尺看两组点','data-kind="dot"')+btn('view','查看记录表','data-kind="table"')+sel('reason','为什么看两组点',m.reason,[['distribution','同时看聚集位置与散开的范围'],['max','只要看最大一个数就够']]);else v+=sel('reason','比较两组要怎样说',m.reason,[['both','同一类别下同时引用A与B的数量'],['one','只说A组，不用看B组']]);}
 if(t.type==='x-correlationlab'){v=!b.started?sel('guess','先猜：拉长纵轴会让联系更紧吗',m.guess,[['same','不会，原来每对数没有换'],['stronger','会，线更陡就是更紧'],['unknown','还不确定']])+btn('start','试试看'):btn('stretch','把纵向拉长 / 还原')+btn('tighten','让点贴近趋势 / 还原')+sel('weather','再换模拟天气',m.weather,[['10','10℃'],['20','20℃'],['30','30℃']])+btn('weather','记录这一种天气')+`<div class="b20-fields">${sel('effect','仅仅拉长纵轴',m.effect,[['same','直线相关程度没变'],['stronger','联系一定更紧']])}${sel('strength','怎样才让点更贴近趋势',m.strength,[['closer','缩小点与共同趋势的偏离'],['steeper','只把线拉陡']])}${sel('causal','在这个人为设定的例子里',m.causal,[['third','天气同时影响两边，不能据此说一边造成另一边'],['direct','一定是冰淇淋让人去游泳']])}</div>`;}
 v+=qfields(t,m);return`<div class="b20-controls">${v}${m.issue?`<p role="status" class="b20-issue">${esc(m.issue)}</p>`:''}<details class="b20-optional"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释是否充分。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;

export function syncControls(t,m,root){if(t.type==='x-scatterbuild'){const el=root.querySelector('[data-b20-fit]');if(el)el.hidden=m.trend==='none';}}
